const items = $input.all();
const output = [];

for (const item of items) {
  const email = item.json || {};
  const fromObj = email.from?.value?.[0] || {};
  const senderName = fromObj.name || (fromObj.address ? fromObj.address.split('@')[0] : 'Technical Recruiter');
  const senderEmail = fromObj.address || '';
  const subject = email.subject || '';
  const text = (email.text || email.html || '').toLowerCase();

  // Identify hiring company from domain or subject
  let company = 'Target Company';
  if (senderEmail.includes('anthropic.com') || subject.toLowerCase().includes('anthropic')) {
    company = 'Anthropic';
  } else if (senderEmail.includes('modal.com') || subject.toLowerCase().includes('modal')) {
    company = 'Modal Labs';
  } else if (senderEmail.includes('vercel.com') || subject.toLowerCase().includes('vercel')) {
    company = 'Vercel';
  } else if (senderEmail.includes('stripe.com') || subject.toLowerCase().includes('stripe')) {
    company = 'Stripe';
  } else if (senderEmail) {
    const domainPart = senderEmail.split('@')[1]?.split('.')[0] || '';
    if (domainPart && !['gmail', 'yahoo', 'outlook', 'proton', 'icloud'].includes(domainPart)) {
      company = domainPart.charAt(0).toUpperCase() + domainPart.slice(1);
    }
  }

  // Detect intent
  let intent = 'STATUS_UPDATE';
  if (text.includes('calendly.com') || text.includes('schedule a call') || text.includes('invitation to interview') || text.includes('chat with the team') || text.includes('introductory call')) {
    intent = 'INTERVIEW_INVITATION';
  } else if (text.includes('technical screen') || text.includes('take-home') || text.includes('coderpad') || text.includes('codesignal')) {
    intent = 'TECHNICAL_SCREEN';
  } else if (text.includes('pleased to offer') || text.includes('next steps') || text.includes('onsite')) {
    intent = 'ADVANCEMENT';
  } else if (text.includes('pursue other candidates') || text.includes('not moving forward') || text.includes('unfortunately')) {
    intent = 'REJECTION';
  }

  // Extract proposed slots or calendar links
  let proposedSlots = 'Flexible Availability';
  const calendlyMatch = (email.text || '').match(/https?:\/\/calendly\.com\/[a-zA-Z0-9_-]+\/[a-zA-Z0-9_-]+/);
  if (calendlyMatch) {
    proposedSlots = 'Self-Schedule Link: ' + calendlyMatch[0];
  } else if (text.includes('tomorrow') || text.includes('monday') || text.includes('tuesday') || text.includes('wednesday') || text.includes('thursday') || text.includes('friday')) {
    proposedSlots = 'Specific Windows Suggested in Email Body';
  }

  // Filter out irrelevant newsletters
  const isRecruiting = text.includes('interview') || text.includes('application') || text.includes('candidate') || text.includes('role') || text.includes('recruiter') || intent !== 'STATUS_UPDATE';

  if (isRecruiting) {
    output.push({
      json: {
        company,
        senderName,
        senderEmail,
        subject,
        intent,
        proposedSlots,
        rawBody: (email.text || '').slice(0, 500),
        appId: company === 'Anthropic' ? 'app-101' : (company === 'Vercel' ? 'app-gh998811' : (company === 'Modal Labs' ? 'app-102' : 'app-101'))
      }
    });
  }
}

return output;
